@router.delete('/api/users/{user_id}/avatar')
async def delete_user_avatar(
    user_id: int,
    db: AsyncSession = Depends(get_db),
    current_user: User = Depends(get_current_user)
):
    if current_user.id != user_id:
        raise HTTPException(status_code=403, detail="Cannot delete another user's avatar")

    result = await db.execute(select(UserProfile).where(UserProfile.user_id == user_id))
    profile = result.scalar_one_or_none()
    if not profile:
        raise HTTPException(status_code=404, detail="Profile not found")

    if profile.avatar_path and os.path.exists(profile.avatar_path):
        os.remove(profile.avatar_path)
        profile.avatar_path = None
        await db.commit()

    return {"status": "avatar deleted"}
